class OverviewStreamVisibilityTest{public static void main(String[]a){int n=64;var w=new TerraForge.World(n,62,71);java.util.Arrays.fill(w.height,800);w.environment.river=new float[n*n];w.environment.water=EnvironmentMap.filled(n*n,62);int i=19*n+19;w.height[i]=799;w.environment.water[i]=800;w.environment.river[i]=1;int sample=EnvironmentView.riverSample(w,4,4,16);if(sample!=i)throw new AssertionError("Off-center thin stream disappears");System.out.println("PASS: off-center narrow streams survive overview sampling and per-pixel terrain coloring");}}
